import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"熱鍵","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/hotkeys.md","filePath":"zh-TW/user-guide/hotkeys.md","lastUpdated":1785993908000}'),a={name:"zh-TW/user-guide/hotkeys.md"};function l(c,t,s,n,h,i){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="熱鍵" tabindex="-1">熱鍵 <a class="header-anchor" href="#熱鍵" aria-label="Permalink to &quot;熱鍵&quot;">​</a></h1><p>下面所有全域與應用程式內熱鍵都可以在<strong>設定 → 熱鍵</strong>裡重新綁定；這裡列出的是預設值。設定介面本身見<a href="./settings/hotkeys-page.html">設定 → 熱鍵頁面</a>。</p><h2 id="全域熱鍵" tabindex="-1">全域熱鍵 <a class="header-anchor" href="#全域熱鍵" aria-label="Permalink to &quot;全域熱鍵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>動作</th><th>預設</th><th>說明</th></tr></thead><tbody><tr><td>叫出/隱藏快速視窗</td><td>按兩下 <code>Ctrl</code></td><td>也可以設定成完整組合鍵(例如 <code>Alt+Space</code>)而不是按兩下模式。</td></tr><tr><td>快速切換</td><td><code>Ctrl+G</code></td><td>在支援的檔案對話框中，跳到最近一次從支援的檔案管理員或快速面板收集的資料夾；內嵌搜尋列為空時也會把該目標顯示成一筆結果。</td></tr><tr><td>選取下一項</td><td><code>Ctrl+N</code></td><td>與方向鍵的下鍵效果相同。在<a href="./settings/quick-panel.html">快速面板</a>裡，它走的是整個標籤而不是單一群組：到了一個群組的末尾會繼續進入下一個群組。</td></tr><tr><td>選取上一項</td><td><code>Ctrl+P</code></td><td>與方向鍵的上鍵效果相同。在快速面板裡同樣是跨群組走完整個標籤。</td></tr><tr><td>跳到結果 1–9</td><td><code>Ctrl</code> + 數字</td><td>輔助鍵可自訂;數字固定為 1–9。快速視窗裡每個可見結果旁邊都會顯示對應快捷鍵的小徽章，不用自己數行數。</td></tr><tr><td>開啟動作選單</td><td><code>Ctrl+O</code></td><td>與在選中結果上按方向鍵右鍵效果相同。</td></tr><tr><td>從選取項補全</td><td><code>Ctrl+Tab</code></td><td>在快速視窗裡，用選取結果的名稱/路徑填入搜尋框。</td></tr><tr><td>QuickLook 預覽</td><td><code>Alt+P</code></td><td>切換選取結果的預覽面板。<a href="./settings/quick-panel.html">快速面板</a>用的是同一個鍵，並且會把預覽視窗停靠到自己放得下的那一側。</td></tr><tr><td>上一條關鍵字歷史</td><td><code>Alt+Up</code></td><td>向前翻閱最近輸入過的搜尋詞。</td></tr><tr><td>下一條關鍵字歷史</td><td><code>Alt+Down</code></td><td>向後翻閱最近輸入過的搜尋詞。</td></tr><tr><td>刪除目前關鍵字歷史</td><td><code>Ctrl+Delete</code></td><td></td></tr><tr><td>開啟完整視窗</td><td><code>Ctrl+F</code></td><td>直接開啟完整視窗並帶上目前搜尋內容——效果和左鍵點選<a href="#搜尋框圖示">快速視窗自帶的圖示</a>、在快显功能表選&quot;顯示主視窗&quot;一樣,只是省了點功能表這一步。可在<strong>設定 → 熱鍵</strong>裡自行設定。</td></tr><tr><td>開啟傳送視窗</td><td><code>Ctrl+S</code></td><td>開啟傳送檔案或文字至 LocalSend 裝置的視窗。可在<strong>設定 → 熱鍵</strong>裡自行設定。</td></tr><tr><td>保持視窗不消失</td><td><code>Ctrl+T</code></td><td>焦點移到別處時不再自動隱藏，便於把其他視窗裡複製來的文字拼成一條查詢——否則每次隱藏都會清空搜尋框。只在本次呼叫期間有效，下次隱藏時解除。在快速視窗裡，滑鼠中鍵點擊 logo 效果相同，開啟期間 logo 會變亮；視窗還在但沒有焦點時按呼出快速鍵，會讓它重新取得焦點而不是隱藏。<a href="./settings/quick-panel.html">快速面板</a>沿用同一個鍵，並以它自己的「釘選」按鈕作為標示。</td></tr><tr><td>呼出/關閉快速面板</td><td><code>Ctrl+F2</code></td><td>把<a href="./settings/quick-panel.html">快速面板</a>停靠到目前前景視窗的右下角；已經開啟時則關閉它。開啟之後，按住「跳到第 1–9 筆結果」的修飾鍵再按 1–9 就能切換工作區。</td></tr></tbody></table><h2 id="搜尋框圖示" tabindex="-1">搜尋框圖示 <a class="header-anchor" href="#搜尋框圖示" aria-label="Permalink to &quot;搜尋框圖示&quot;">​</a></h2><p>搜尋框裡那個小圖示(具體在左側還是右側,取決於視窗)在<a href="./getting-started.html#三種視窗">三種視窗</a>裡各自有不同的作用：</p><ul><li><p><strong>快速視窗</strong> —— 左鍵點擊(不移動)會彈出和系統匣圖示右鍵一樣的選單(顯示主視窗、切換熱鍵、設定、關於、乾淨結束、結束)，選單出現在游標位置；選單裡的「顯示主視窗」還會帶上你目前輸入框裡的搜尋內容。按住左鍵拖曳會移動視窗，和拖曳搜尋列其它部分一樣——拖曳時(不管是拖搜尋列還是拖圖示)按住 <strong>Ctrl</strong> 可以把移動方向限制成只能縱向，拖到一半按下/放開 Ctrl 也能即時生效，適合只想上下調整位置而不想帶偏橫向位置的時候用。右鍵點擊會把視窗重設回預設螢幕位置(不影響大小)——和首次啟動時的置中位置相同。滑鼠停留時的提示會把這三種手勢都列出來。</p><p>記住的位置是相對於上次所在顯示器的相對位置，不是絕對螢幕座標——換到另一台顯示器(或者解析度、 DPI 縮放不同的顯示器)上叫出時，會在那塊螢幕上按比例換算到對應位置，而不會跑出螢幕外或落到錯誤的顯示器上。</p></li><li><p><strong>內嵌視窗</strong> —— 只有當視窗停靠在原生的開啟/儲存/瀏覽資料夾對話方塊上時才可點擊：左鍵點擊會觸發<a href="#快速導覽-滑鼠">快速導覽</a>，效果和下面專門的觸發方式一樣。當停靠在一般檔案總管視窗或桌面上時不可點擊，因為那種情況下沒有什麼可供跳轉的目標——這時既不會有滑鼠停留高亮，也不會有提示。</p></li><li><p><strong>主視窗</strong> —— 這個圖示在主視窗裡純粹是裝飾性的，點擊沒有任何效果。</p></li></ul><h2 id="快速導覽-滑鼠" tabindex="-1">快速導覽(滑鼠) <a class="header-anchor" href="#快速導覽-滑鼠" aria-label="Permalink to &quot;快速導覽(滑鼠)&quot;">​</a></h2><p>預設啟用，每種觸發方式都可單獨在設定裡開關：</p><ul><li>在桌面或檔案總管視窗的空白處<strong>按兩下左鍵</strong>觸發快速導覽。</li><li>在桌面或檔案總管視窗的空白處、受支援的第三方檔案管理員(Directory Opus、Total Commander、 XYplorer、Files 等)的檔案清單區域、或原生的開啟/儲存/瀏覽資料夾對話方塊裡<strong>點擊中鍵</strong>觸發快速導覽。這些其它視窗只回應中鍵——按兩下在那裡已經是「開啟這一項」的意思，所以沒有把按兩下挪作他用。參見<a href="./file-manager-support.html">支援的檔案管理員</a>了解每種整合具體涵蓋哪些能力。</li><li>當內嵌搜尋視窗停靠在原生的開啟/儲存/瀏覽資料夾對話方塊上時，它自己的圖示同樣可以觸發快速導覽 ——見上面的<a href="#搜尋框圖示">搜尋框圖示</a>。</li></ul><p>無論哪種方式觸發，都會彈出一個串接式選單，內容是你的我的最愛、歷史記錄和設定好的捷徑資料夾(見<a href="./settings/favorites.html">設定 → 我的最愛</a>和<a href="./settings/history.html">設定 → 歷史記錄</a>)——外掛也可以往裡新增自己的項目，比如你在 <code>wincmd.ini</code> 裡設定過 Total Commander 的 Directory Hotlist 的話，它也會出現在這裡，Directory Opus 自己的我的最愛選單同樣如此，或者是某條勾選了「在快速導覽中顯示」的<a href="./instant-answers.html#自訂命令">自訂命令</a>(可以透過 <code>/</code> 分隔的路徑把它歸到某個子選單下)。每個貢獻項目的外掛在選單根層級都有自己獨立的標題分組，這些分組的先後順序可以自己調整——見<a href="./settings/general.html#快速導覽">設定 → 通用 → 快速導覽</a>。點擊資料夾會讓目標視窗跳轉過去；點擊檔案也會跳轉過去，並在其所在資料夾中選取該檔案，而不是開啟它——唯一的例外是桌面，那裡沒有可供跳轉的現有視窗面板，所以在桌面上點擊資料夾或檔案會直接開啟它，效果和按兩下一樣。如果是在檔案選擇器裡，點擊檔案則是讓對話方塊跳轉到該檔案所在的資料夾——絕不會替你自動確認「開啟」/「儲存」。</p><p>這個選單實際上是由<strong>串接式資料夾瀏覽器</strong>外掛建構的。除了可以各自獨立開關的我的最愛和歷史記錄，它還有自己的一份可設定捷徑資料夾清單——在<strong>設定 → 外掛 → 串接式資料夾瀏覽器 → 設定</strong>裡新增路徑和可選的顯示名稱，再給它填一個 Submenu 值(比如 <code>工具/網路</code>，用 <code>/</code> 分隔可以巢狀多層)，就能把它歸到某個分類下而不是直接顯示在根層級。選單的每一層——根層級和任意巢狀分類——的標題上都有一個小小的 <strong>+</strong> 按鈕：點它可以把你目前瀏覽到的資料夾直接加進來，名稱、路徑和這一層自己的子選單路徑都會預先填好(新增前仍可編輯)，不用離開選單去設定裡操作。</p><h2 id="硬編碼按鍵-不可設定" tabindex="-1">硬編碼按鍵(不可設定) <a class="header-anchor" href="#硬編碼按鍵-不可設定" aria-label="Permalink to &quot;硬編碼按鍵(不可設定)&quot;">​</a></h2><p>無論熱鍵設定如何，以下按鍵始終保持相同行為：</p><table tabindex="0"><thead><tr><th>按鍵</th><th>情境</th><th>行為</th></tr></thead><tbody><tr><td><code>Escape</code></td><td>任意情境</td><td>若搜尋框有內容則清空;否則關閉視窗(或退出動作選單)。</td></tr><tr><td><code>Enter</code></td><td>結果清單</td><td>開啟選取結果。</td></tr><tr><td><code>Ctrl+Enter</code></td><td>結果清單</td><td>在檔案總管中定位該結果，而不是開啟它。</td></tr><tr><td><code>Ctrl+Shift+Enter</code></td><td>結果清單</td><td>以系統管理員身分開啟該結果。</td></tr><tr><td>左/右方向鍵</td><td>動作選單</td><td>返回上一層選單 / 進入子選單。</td></tr><tr><td><code>Backspace</code></td><td>動作選單</td><td>當搜尋框已為空時，退出動作選單。</td></tr><tr><td><code>Alt+Space</code> / <code>Alt+F4</code></td><td>Lertaro 的所有視窗</td><td><code>Alt+Space</code> 在所有視窗上都會被封鎖——它們都沒有真正的標題列，Windows 的系統選單在這裡無處可依。<code>Alt+F4</code> 在主視窗和設定視窗上照常關閉視窗；在快速視窗、內嵌視窗、QuickLook 以及各類對話方塊上仍然被封鎖，因為它們是顯示/隱藏的，而不是開啟/關閉的。</td></tr></tbody></table><h2 id="外掛動作熱鍵" tabindex="-1">外掛動作熱鍵 <a class="header-anchor" href="#外掛動作熱鍵" aria-label="Permalink to &quot;外掛動作熱鍵&quot;">​</a></h2><p>外掛可以註冊自己的動作並附帶一個預設熱鍵(例如複製路徑 <code>Ctrl+Shift+C</code>、以系統管理員身分執行，或是內建的檔案操作動作——剪下 <code>Ctrl+X</code>、複製 <code>Ctrl+C</code>、貼上 <code>Ctrl+V</code>、刪除 <code>Delete</code>、徹底刪除 <code>Shift+Delete</code>)。這些會顯示在<strong>設定 → 熱鍵 → 外掛動作</strong> 裡，按註冊它們的外掛分組，重新綁定方式和內建熱鍵相同。</p><h2 id="處理程序黑名單" tabindex="-1">處理程序黑名單 <a class="header-anchor" href="#處理程序黑名單" aria-label="Permalink to &quot;處理程序黑名單&quot;">​</a></h2><p>如果 Lertaro 的全域熱鍵和某個應用程式(比如會獨佔鍵盤原始輸入的遊戲)衝突，把該處理程序加入<strong>處理程序黑名單</strong>即可——詳見<a href="./settings/hotkeys-page.html#process-blacklist">設定 → 熱鍵頁面</a>。當黑名單裡的處理程序處於前景時，Lertaro 的全域熱鍵、按鍵攔截，以及上面的快速導覽滑鼠觸發都會被完全放行，不會攔截。</p><p>任何真正全螢幕的前景應用程式都會自動取得同樣的效果，不需要手動加入黑名單。無論哪種情況，目前作用中視窗如果是檔案選擇器，都會被豁免，快速導覽依然可以正常使用。</p>',20)])])}const u=d(a,[["render",l]]);export{g as __pageData,u as default};
